import * as React from 'react';
import { cn } from '@/lib/utils';

export type TableCardProps = React.HTMLAttributes<HTMLDivElement> & {
  title?: string;
  description?: string;
  /** Right-aligned header actions (create, export, column settings). */
  actions?: React.ReactNode;
  /** Row between the header and the table (filters, bulk actions). */
  toolbar?: React.ReactNode;
  /** Table/DataTable content. */
  children: React.ReactNode;
  /** Rendered under the table (pagination, summary). */
  footer?: React.ReactNode;
  /** Remove the inner padding so table edges reach the card border. */
  flush?: boolean;
};

/**
 * Table shell: title/description + actions, an optional toolbar, an
 * edge-to-edge table body and a footer row. Standardizes the chrome every
 * list page grows around a Table or DataTable.
 */
export const TableCard = React.forwardRef<HTMLDivElement, TableCardProps>(function TableCard(
  { title, description, actions, toolbar, children, footer, flush = true, className, ...props },
  ref
) {
  return (
    <div
      ref={ref}
      className={cn('overflow-hidden rounded-xl border border-border bg-card text-card-foreground', className)}
      {...props}
    >
      {(title || description || actions) && (
        <div className="flex flex-wrap items-start justify-between gap-3 border-b border-border px-4 py-3">
          <div className="min-w-0">
            {title && <h2 className="text-sm font-semibold">{title}</h2>}
            {description && <p className="mt-0.5 text-sm text-muted-foreground">{description}</p>}
          </div>
          {actions && <div className="flex shrink-0 items-center gap-2">{actions}</div>}
        </div>
      )}
      {toolbar && <div className="border-b border-border px-4 py-2">{toolbar}</div>}
      <div className={cn(flush ? 'overflow-x-auto' : 'p-4')}>{children}</div>
      {footer && <div className="border-t border-border px-4 py-3">{footer}</div>}
    </div>
  );
});

{
  "id": "table-card",
  "name": "TableCard",
  "tier": "molecule",
  "package": "@slipstream-ui/core",
  "importPath": "@slipstream-ui/core",
  "version": "0.1.0",
  "sourceDir": "table-card",
  "exportName": "TableCard",
  "description": "Table shell with title/description, header actions, optional toolbar, edge-to-edge body and a footer row.",
  "designIntent": "Every list page rebuilds the same chrome around Table/DataTable: heading, count, actions, filter row, pagination. TableCard standardizes that shell so pages only supply the table.",
  "props": [
    {
      "name": "title",
      "type": "string",
      "required": false,
      "description": "Card heading."
    },
    {
      "name": "description",
      "type": "string",
      "required": false,
      "description": "Supporting line under the heading."
    },
    {
      "name": "actions",
      "type": "ReactNode",
      "required": false,
      "description": "Right-aligned header actions."
    },
    {
      "name": "toolbar",
      "type": "ReactNode",
      "required": false,
      "description": "Row between header and table (filters, bulk actions)."
    },
    {
      "name": "children",
      "type": "ReactNode",
      "required": true,
      "description": "Table or DataTable content."
    },
    {
      "name": "footer",
      "type": "ReactNode",
      "required": false,
      "description": "Footer row (pagination, summary)."
    },
    {
      "name": "flush",
      "type": "boolean",
      "required": false,
      "defaultValue": "true",
      "description": "Remove inner padding so the table reaches the card edges."
    }
  ],
  "examples": [
    {
      "title": "List page table",
      "code": "<TableCard\n  title=\"Classes\"\n  description=\"12 active\"\n  actions={<Button>New class</Button>}\n  toolbar={<FilterBar … />}\n  footer={<Pagination … />}\n>\n  <DataTable columns={columns} data={rows} />\n</TableCard>",
      "description": "Header, toolbar, table and pagination in one surface."
    }
  ],
  "antiPatterns": [
    {
      "title": "Don't nest another bordered card",
      "explanation": "TableCard is the surface; wrapping it in Card double-borders the content.",
      "example": "// Avoid\n<Card><TableCard>…</TableCard></Card>"
    }
  ],
  "accessibility": [
    {
      "feature": "Heading semantics",
      "implementation": "Title renders an h2 (page owns the h1 via PageHeader)",
      "userRequirements": "Don't skip heading levels"
    },
    {
      "feature": "Table labelling",
      "implementation": "The table keeps its own caption/aria-label",
      "userRequirements": "Always label the table inside"
    }
  ],
  "contentGuidelines": [
    {
      "contentType": "Titles",
      "guidelines": [
        "Plural noun",
        "Sentence case",
        "Pair with a count in description"
      ],
      "goodExamples": [
        "Classes · 12 active"
      ],
      "badExamples": [
        "Data"
      ]
    }
  ],
  "compositionRules": [
    {
      "component": "DataTable",
      "relationship": "Body content; use flush for edge-to-edge rows",
      "example": "<TableCard flush><DataTable … /></TableCard>"
    },
    {
      "component": "FilterBar",
      "relationship": "Pass as toolbar for list filtering",
      "example": "<TableCard toolbar={<FilterBar … />}>…</TableCard>"
    },
    {
      "component": "Pagination",
      "relationship": "Pass as footer",
      "example": "<TableCard footer={<Pagination … />}>…</TableCard>"
    }
  ],
  "relatedComponents": [
    "DataTable",
    "Table",
    "FilterBar",
    "Pagination",
    "Card"
  ]
}
